import { GlideRecord } from '@servicenow/glide'

export function getMatrix() {
    var result = [];
    var gr = new GlideRecord('x_snc_habitat_matrice_eligibilite');
    gr.orderBy('site_depart');
    gr.orderBy('site_arrivee');
    gr.orderBy('ordre');
    gr.query();
    while (gr.next()) {
        result.push({
            site_depart: gr.getValue('site_depart') + '',
            site_arrivee: gr.getValue('site_arrivee') + '',
            categorie: gr.getValue('categorie') + '',
            code_offre: gr.getValue('code_offre') + '',
            offre: gr.getValue('offre') + '',
            condition_text: gr.getValue('condition_text') + '',
            ordre: parseInt(gr.getValue('ordre') || '0', 10)
        });
    }
    return result;
}

export function getOffresObj(depart, arrivee) {
    var offres = {
        logement: [],
        demenagement: [],
        accompagnement: []
    };

    var gr = new GlideRecord('x_snc_habitat_matrice_eligibilite');
    gr.addQuery('site_depart', depart);
    gr.addQuery('site_arrivee', arrivee);
    gr.orderBy('categorie');
    gr.orderBy('ordre');
    gr.query();

    while (gr.next()) {
        var item = {
            code_offre: gr.getValue('code_offre') + '',
            offre: gr.getValue('offre') + '',
            condition_text: gr.getValue('condition_text') + '',
            ordre: parseInt(gr.getValue('ordre') || '0', 10)
        };

        var cat = gr.getValue('categorie') + '';
        if (cat === 'logement') {
            offres.logement.push(item);
        } else if (cat === 'demenagement') {
            offres.demenagement.push(item);
        } else if (cat === 'accompagnement') {
            offres.accompagnement.push(item);
        }
    }

    return offres;
}
